  struct _VectorArgs { ::flatbuffers::FlatBufferBuilder *__fbb; const ACWT* __o; const ::flatbuffers::rehasher_function_t *__rehasher; } _va = { &_fbb, _o, _rehasher}; (void)_va;
  auto _REQUEST = _o->REQUEST ? CreateACWRequest(_fbb, _o->REQUEST.get(), _rehasher) : 0;
  auto _RESULT = _o->RESULT ? CreateACWResult(_fbb, _o->RESULT.get(), _rehasher) : 0;
